-- Frozen EF/Neon baseline; generated from the reviewed fixture, not a live DB.
-- The same migration creates a fresh schema or adopts exactly the frozen EF state.
-- No catalogue data is copied, dropped or rewritten. See ../baseline/README.md.
DO $archive_baseline$
DECLARE
    actual_fingerprint text;
    original_search_path text := current_setting('search_path');
BEGIN
    PERFORM pg_catalog.set_config('search_path', 'pg_catalog', true);
    IF to_regclass('public."__EFMigrationsHistory"') IS NULL THEN
        IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            WHERE n.nspname='public' AND c.relname NOT IN ('_sqlx_migrations', '_sqlx_migrations_pkey'))
            OR EXISTS (SELECT FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public')
            OR EXISTS (SELECT FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typrelid=0 AND t.typelem=0) THEN
            RAISE EXCEPTION 'Not an empty database or the frozen EF baseline';
        END IF;
