CREATE TABLE public.dateien (
    "Id" uuid NOT NULL,
    "LiedId" uuid,
    "EventId" uuid,
    "Kind" character varying(20) NOT NULL,
    "IsPartitur" boolean NOT NULL,
    "Stimme" character varying(200),
    "Description" character varying(500),
    "RecordedAtEventId" uuid,
    "BlobName" character varying(300) NOT NULL,
    "ContentType" character varying(100) NOT NULL,
    "SizeBytes" bigint NOT NULL,
    "OriginalFileName" character varying(300),
    "CreatedByAccountId" uuid NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "DeletedAt" timestamp with time zone,
    "DeletedByAccountId" uuid,
    "ReplacedByDateiId" uuid,
    "RowVersion" bigint NOT NULL,
    "StorageTier" character varying(10) DEFAULT 'hot'::character varying NOT NULL,
    "TierChangedAt" timestamp with time zone,
    CONSTRAINT "CK_dateien_kind" CHECK ((("Kind")::text = ANY ((ARRAY['noten'::character varying, 'uebe'::character varying, 'aufnahme'::character varying, 'sonstiges'::character varying])::text[]))),
    CONSTRAINT "CK_dateien_owner" CHECK ((((("LiedId" IS NOT NULL))::integer + (("EventId" IS NOT NULL))::integer) = 1)),
    CONSTRAINT "CK_dateien_partitur" CHECK (((NOT "IsPartitur") OR (("Kind")::text = 'noten'::text))),
    CONSTRAINT "CK_dateien_storage_tier" CHECK ((("StorageTier")::text = ANY ((ARRAY['hot'::character varying, 'cold'::character varying])::text[])))
);


